    void playerInvoke(PlayerActivity viewer,String name,Class<?>[] types,Object...args)throws Exception{Method method=PlayerActivity.class.getDeclaredMethod(name,types);method.setAccessible(true);runOnMainSync(()->{try{method.invoke(viewer,args);}catch(Exception e){throw new RuntimeException(e);}});}
    void visibleVideo(PlayerActivity viewer,String message)throws Exception{
        waitFor(()->Boolean.TRUE.equals(playerField(viewer,"haveVideoFrame")),15000);long stamp=(Long)playerField(viewer,"textureTimestamp");waitFor(()->(Long)playerField(viewer,"textureTimestamp")!=stamp,6000);waitForIdleSync();
        int[] rect=new int[4];runOnMainSync(()->{View frame=(View)uncheckedPlayerField(viewer,"video");frame.getLocationOnScreen(rect);rect[2]=frame.getWidth();rect[3]=frame.getHeight();});Bitmap screenshot=getUiAutomation().takeScreenshot();int colored=0;Set<Integer> colors=new HashSet<>();for(int y=rect[3]/4;y<rect[3]*3/4;y+=9)for(int x=rect[2]/8;x<rect[2]*7/8;x+=9){int pixel=screenshot.getPixel(rect[0]+x,rect[1]+y);if(Color.red(pixel)+Color.green(pixel)+Color.blue(pixel)>90)colored++;colors.add(pixel);}screenshot.recycle();check(colored>20&&colors.size()>8,message);
    }
    Object uncheckedPlayerField(PlayerActivity viewer,String name){try{return playerField(viewer,name);}catch(Exception e){throw new RuntimeException(e);}}
    byte[] readHttp(String url,String range)throws Exception{HttpURLConnection conn=(HttpURLConnection)new URL(url).openConnection();if(range!=null)conn.setRequestProperty("Range",range);try{if(range!=null&&conn.getResponseCode()!=206)throw new IOException("Expected partial HTTP response");try(InputStream in=conn.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>4*1024*1024)throw new IOException("Unbounded test range response");out.write(buffer,0,n);}return out.toByteArray();}}finally{conn.disconnect();}}
    void auditPlayback(JieliSession session)throws Exception{
        fixture("card/1");session.get("SD_STATUS");activity.getSharedPreferences("playback",0).edit().clear().commit();
        String path="/storage/fullhd-zero200.MOV";long total;
        try(WifiMediaProxy relay=new WifiMediaProxy(session.network,session.url(path))){
            HttpURLConnection head=(HttpURLConnection)new URL(relay.address()).openConnection();head.setRequestMethod("HEAD");check(head.getResponseCode()==200,"HEAD probes movie metadata without streaming its body");total=head.getContentLengthLong();head.disconnect();check(total>130_000_000,"Fixture exercises a 60-second Full HD MOV larger than 130MB");
            byte[] expected=readHttp("http://10.0.2.2:8080/storage/fullhd.MOV","bytes=100000-199999"),actual=readHttp(relay.address(),"bytes=100000-199999");check(Arrays.equals(expected,actual),"Bounded Wi-Fi range reads preserve the original MOV bytes");
            byte[] tail=readHttp(relay.address(),"bytes=-100");check(Arrays.equals(tail,readHttp("http://10.0.2.2:8080/storage/fullhd.MOV","bytes="+(total-100)+"-")),"Suffix ranges read the real tail containing MOV index data");
            HttpURLConnection eof=(HttpURLConnection)new URL(relay.address()).openConnection();eof.setRequestProperty("Range","bytes="+total+"-");check(eof.getResponseCode()==416&&("bytes */"+total).equals(eof.getHeaderField("Content-Range")),"Seeking exactly past EOF returns valid 416 rather than a broken 206");eof.disconnect();
            HttpURLConnection wrong=(HttpURLConnection)new URL(relay.address()).openConnection();wrong.setRequestProperty("Range","bytes=5-2");check(wrong.getResponseCode()==416,"Reversed ranges are rejected");wrong.disconnect();
        }
        try(WifiMediaProxy relay=new WifiMediaProxy(session.network,session.url("/storage/fullhd-drop.MOV"))){check(Arrays.equals(readHttp(relay.address(),"bytes=0-1199999"),readHttp("http://10.0.2.2:8080/storage/fullhd.MOV","bytes=0-1199999")),"A mid-range Wi-Fi disconnect resumes at the exact byte without duplication");}
        try(WifiMediaProxy relay=new WifiMediaProxy(session.network,session.url("/storage/fullhd-quirks.MOV"))){check(Arrays.equals(readHttp(relay.address(),"bytes=100000-199999"),readHttp("http://10.0.2.2:8080/storage/fullhd.MOV","bytes=100000-199999")),"Relay bounds its response even when firmware ignores the requested end offset");HttpURLConnection eof=(HttpURLConnection)new URL(relay.address()).openConnection();eof.setRequestProperty("Range","bytes="+total+"-");check(eof.getResponseCode()==416,"Firmware with broken open-ended/EOF responses still exposes a valid EOF to VLC");eof.disconnect();}
        Intent intent=new Intent(activity,PlayerActivity.class).putExtra("uri",session.url(path).toString()).putExtra("mime","video/quicktime").putExtra("name","Full HD 60s MOV").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        PlayerActivity viewer=(PlayerActivity)startActivitySync(intent);waitFor(()->playerField(viewer,"player")!=null&&((org.videolan.libvlc.MediaPlayer)playerField(viewer,"player")).getTime()>500,18000);org.videolan.libvlc.MediaPlayer player=(org.videolan.libvlc.MediaPlayer)playerField(viewer,"player");
        check(player.getLength()>59000&&player.getCurrentVideoTrack().width==1920,"Large MOV duration and 1920-pixel video track are recognized");visibleVideo(viewer,"Full HD MOV displays changing video pixels, not just an advancing clock");mediaScreen("16-fullhd-visible.png");
        long before=(Long)playerField(viewer,"textureTimestamp");runOnMainSync(()->player.setTime(45000));waitFor(()->player.getTime()>=44500,15000);visibleVideo(viewer,"Full HD picture resumes after seeking to 45 seconds");check((Long)playerField(viewer,"textureTimestamp")!=before,"Seek displays new frames");
        runOnMainSync(()->player.setTime(2000));waitFor(()->player.getTime()<12000,10000);visibleVideo(viewer,"Seeking backwards restores visible video");
        playerInvoke(viewer,"applySpeed",new Class<?>[]{float.class,boolean.class},2f,false);visibleVideo(viewer,"Accelerated playback continues to display changing frames");playerInvoke(viewer,"applySpeed",new Class<?>[]{float.class,boolean.class},.5f,false);visibleVideo(viewer,"Slow motion continues to display changing frames");
        playerInvoke(viewer,"restartDecoder",new Class<?>[]{boolean.class},true);waitFor(()->player.getTime()>500,10000);visibleVideo(viewer,"Compatible software decoding displays the same Full HD MOV");check(player.getRate()==.5f,"Decoder changes retain playback speed");
        playerInvoke(viewer,"restartDecoder",new Class<?>[]{boolean.class},false);waitFor(()->Boolean.TRUE.equals(playerField(viewer,"haveVideoFrame")),15000);playerInvoke(viewer,"applySpeed",new Class<?>[]{float.class,boolean.class},1f,false);
        runOnMainSync(()->player.setVideoTrack(-1));waitFor(()->Boolean.TRUE.equals(playerField(viewer,"softwareDecoder")),20000);visibleVideo(viewer,"An injected video-output stall automatically recovers through software decoding");check(Boolean.TRUE.equals(playerField(viewer,"automaticFallback")),"Automatic fallback is bounded to one attempt per recording");
        runOnMainSync(()->viewer.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE));waitFor(()->viewer.getResources().getConfiguration().orientation==2,5000);visibleVideo(viewer,"Landscape rotation retains moving Full HD video");mediaScreen("17-fullhd-landscape.png");runOnMainSync(viewer::finish);waitFor(viewer::isDestroyed,5000);
    }
