    int recordedAudioEnergy(Uri uri)throws Exception{
        MediaExtractor extractor=new MediaExtractor();MediaCodec decoder=null;try{extractor.setDataSource(activity,uri,null);int track=-1;for(int i=0;i<extractor.getTrackCount();i++)if("audio/mp4a-latm".equals(extractor.getTrackFormat(i).getString(MediaFormat.KEY_MIME)))track=i;check(track>=0,"Saved recording has an AAC track");extractor.selectTrack(track);MediaFormat format=extractor.getTrackFormat(track);decoder=MediaCodec.createDecoderByType("audio/mp4a-latm");decoder.configure(format,null,null,0);decoder.start();boolean eos=false;int maximum=0;long end=System.currentTimeMillis()+6000;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(System.currentTimeMillis()<end&&maximum<=500){if(!eos){int input=decoder.dequeueInputBuffer(1000);if(input>=0){ByteBuffer buffer=decoder.getInputBuffer(input);int n=extractor.readSampleData(buffer,0);if(n<0){decoder.queueInputBuffer(input,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);eos=true;}else{decoder.queueInputBuffer(input,0,n,extractor.getSampleTime(),0);extractor.advance();}}}int output=decoder.dequeueOutputBuffer(info,1000);if(output>=0){ByteBuffer buffer=decoder.getOutputBuffer(output).order(ByteOrder.LITTLE_ENDIAN);buffer.position(info.offset);buffer.limit(info.offset+info.size);while(buffer.remaining()>=2)maximum=Math.max(maximum,Math.abs((int)buffer.getShort()));decoder.releaseOutputBuffer(output,false);if((info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0)break;}}return maximum;}finally{extractor.release();if(decoder!=null){decoder.stop();decoder.release();}}
    }
