    void checkBounds(View view,int[] bad){if(view.getVisibility()!=View.VISIBLE||!view.isShown())return;if(view instanceof Button button){android.graphics.Rect visible=new android.graphics.Rect();if(view.getGlobalVisibleRect(visible)){float density=activity.getResources().getDisplayMetrics().density;if(visible.width()<view.getWidth()-2||view.getWidth()<48*density-1||view.getHeight()<48*density-1)bad[0]++;android.text.Layout layout=button.getLayout();if(layout!=null)for(int line=0;line<layout.getLineCount();line++)if(layout.getEllipsisCount(line)>0)bad[0]++;}}if(view instanceof android.view.ViewGroup group)for(int i=0;i<group.getChildCount();i++)checkBounds(group.getChildAt(i),bad);}
    void saveScreen(String name)throws Exception {Bitmap bitmap=getUiAutomation().takeScreenshot();File dir=new File(activity.getExternalFilesDir(null),"ui-audit");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    Object getPrivate(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    Map<String,Long> logSizes(File dir){Map<String,Long> result=new TreeMap<>();for(File f:Objects.requireNonNull(dir.listFiles()))result.put(f.getName(),f.length());return result;}
